from math import pi, cos, sqrtdef distance(x1, y1, x2, y2):    return sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)def path(v:float, time:float)->float:    return v * time# Скорость ракеты 1550 м/c# Скорость цели до 3000 м/с на встречном курсеB = int(input())S = int(input())a = int(input())b = int(input())H = int(input())Vr = int(input())Vt = int(input())c = b - aS = sqrt(S ** 2 - H ** 2)  # дальность до цели на плоскостиSpzugor = sqrt(B ** 2 + S ** 2 - 2 * B * S * cos(c * pi / 180))  # дальность с ПЗУ до цели горизонтальнаяSpzu = sqrt(H ** 2 + Spzugor ** 2)t = Spzu / (Vr + Vt)answer = t * Vrprint(f"{answer:.2f}")